#include "queue.h"
#include <string.h>
#include <limits.h>
_Static_assert(offsetof(struct live_shared,slots)==64,"shared header ABI");
_Static_assert(offsetof(struct live_slot,data)==32,"frame header ABI");
static uint32_t get(const uint32_t *p){return __atomic_load_n(p,__ATOMIC_ACQUIRE);}
static void put(uint32_t *p,uint32_t v){__atomic_store_n(p,v,__ATOMIC_RELEASE);}
static int valid(struct live_peer *p){struct live_shared *q=p?p->q:0;return q&&get(&q->magic)==LIVE_MAGIC&&q->version==1&&q->bytes==sizeof(*q)&&q->capacity==LIVE_CAPACITY&&q->producer_pid==p->producer_pid&&q->consumer_pid==p->consumer_pid&&!memcmp(q->nonce,p->nonce,16)&&!q->reserved&&!get(&q->closed);}
static int damaged(struct live_shared *q){put(&q->dropped,get(&q->dropped)+1);put(&q->request_idr,1);return -1;}
static unsigned prefix(const unsigned char *p,size_t n){if(n>=4&&!p[0]&&!p[1]&&!p[2]&&p[3]==1)return 4;if(n>=3&&!p[0]&&!p[1]&&p[2]==1)return 3;return 0;}
static unsigned scan(const unsigned char *p,size_t n){size_t i=0;unsigned flags=0,k,t;if(!p||!n||!prefix(p,n))return UINT_MAX;while(i<n){k=prefix(p+i,n-i);if(!k){i++;continue;}i+=k;if(i>=n||(p[i]&128))return UINT_MAX;t=p[i]&31;if(!t||t>=24)return UINT_MAX;if(t==5)flags|=LIVE_IDR|LIVE_SLICE;if(t==1)flags|=LIVE_SLICE;if(t==7)flags|=LIVE_SPS;if(t==8)flags|=LIVE_PPS;i++;}return flags;}
int live_init(void *memory,size_t bytes,const uint32_t nonce[4],uint32_t producer,uint32_t consumer){struct live_shared *q=memory;if(!q||bytes!=sizeof(*q)||!nonce||!(nonce[0]|nonce[1]|nonce[2]|nonce[3])||!producer||!consumer||producer==consumer)return -1;memset(q,0,64);q->version=1;q->bytes=sizeof(*q);q->capacity=LIVE_CAPACITY;q->request_idr=1;q->producer_pid=producer;q->consumer_pid=consumer;memcpy(q->nonce,nonce,16);put(&q->magic,LIVE_MAGIC);return 0;}
int live_bind(struct live_peer *p,void *memory,size_t bytes,const uint32_t nonce[4],uint32_t producer,uint32_t consumer){if(!p)return -1;memset(p,0,sizeof(*p));if(!memory||bytes!=sizeof(struct live_shared)||!nonce)return -1;p->q=memory;p->producer_pid=producer;p->consumer_pid=consumer;memcpy(p->nonce,nonce,16);p->need_idr=1;if(!valid(p)){p->q=0;return -1;}p->epoch=get(&p->q->dropped);return 0;}
int live_publish(struct live_peer *p,const void *codec,size_t nc,const void *body,size_t nb,uint32_t session,uint64_t timestamp){struct live_shared *q;struct live_slot *s;uint32_t h,t;unsigned flags,cf=0;if(!valid(p))return -1;q=p->q;if(!nb||nb>LIVE_AU_LIMIT||nc>65536||nc>LIVE_AU_LIMIT-nb||(nc&&!codec))return damaged(q);flags=scan(body,nb);if(flags==UINT_MAX||!(flags&LIVE_SLICE))return damaged(q);if(nc){cf=scan(codec,nc);if(cf==UINT_MAX||(cf&LIVE_SLICE))return damaged(q);}h=get(&q->head);t=get(&q->tail);if(h-t>LIVE_CAPACITY)return -1;if(h-t==LIVE_CAPACITY){put(&q->dropped,get(&q->dropped)+1);put(&q->request_idr,1);return 0;}s=&q->slots[h%LIVE_CAPACITY];s->bytes=(uint32_t)(nc+nb);s->sequence=h;s->session=session;s->flags=flags|cf;s->timestamp=timestamp;s->reserved[0]=s->reserved[1]=0;if(nc)memcpy(s->data,codec,nc);memcpy(s->data+nc,body,nb);put(&q->head,h+1);return 1;}
static int resync(struct live_peer *p,uint32_t head,uint32_t epoch){p->epoch=epoch;p->need_idr=1;p->have_timestamp=0;put(&p->q->request_idr,1);put(&p->q->tail,head);return 0;}
int live_consume(struct live_peer *p,void *out,size_t capacity,struct live_frame *frame){struct live_shared *q;struct live_slot *s;uint32_t h,t,epoch,n,flags,session;uint64_t ts;if(!out||!frame||!valid(p))return -1;q=p->q;h=get(&q->head);t=get(&q->tail);epoch=get(&q->dropped);if(h-t>LIVE_CAPACITY)return -1;if(epoch!=p->epoch)return resync(p,h,epoch);if(h==t)return 0;s=&q->slots[t%LIVE_CAPACITY];n=s->bytes;flags=s->flags;session=s->session;ts=s->timestamp;if(s->sequence!=t||!n||n>LIVE_AU_LIMIT||n>capacity||s->reserved[0]||s->reserved[1]||flags>15){put(&q->tail,t+1);p->need_idr=1;put(&q->request_idr,1);return -1;}if(!p->have_session||p->session!=session){p->need_idr=1;p->have_timestamp=0;p->session=session;p->have_session=1;}if(p->have_timestamp&&ts<p->last_timestamp){put(&q->tail,t+1);p->need_idr=1;p->have_timestamp=0;put(&q->request_idr,1);return -1;}if(p->need_idr&&(flags&7)!=7){put(&q->tail,t+1);put(&q->request_idr,1);return 0;}memcpy(out,s->data,n);if(scan(out,n)!=flags){put(&q->tail,t+1);p->need_idr=1;put(&q->request_idr,1);return -1;}put(&q->tail,t+1);epoch=get(&q->dropped);if(epoch!=p->epoch)return resync(p,get(&q->head),epoch);frame->flags=flags|(p->need_idr?LIVE_RESYNC:0);p->need_idr=0;p->last_timestamp=ts;p->have_timestamp=1;put(&q->request_idr,0);frame->bytes=n;frame->session=session;frame->timestamp=ts;return 1;}
int live_close(struct live_peer *p){if(!valid(p))return -1;put(&p->q->closed,1);return 0;}
